CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM integration.get_purchase_updates('2020-06-15 11:00:00.000000'::timestamp, '2020-06-15 13:00:00.000000'::timestamp);
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['Date Key', 'WWI Purchase Order ID', 'Ordered Outers', 'Ordered Quantity', 'Received Outers', 'Package', 'Is Order Finalized', 'WWI Supplier ID', 'WWI Stock Item ID', 'Last Modified When']::text[] THEN
