  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 window edges to the microsecond (at @LastCutoff excluded, +1 µs included, at @NewCutoff included, +1…', missing, extra;
  END IF;
END $pp$;
